import { Entity, PrimaryGeneratedColumn, Column, ManyToOne, Index, CreateDateColumn } from "typeorm";

@Entity("users")
export class User {
  @PrimaryGeneratedColumn("uuid")
  id!: string;

  @Column()
  email!: string;
}

@Entity("devices")
export class Device {
  @PrimaryGeneratedColumn("uuid")
  id!: string;

  @Index({ unique: true })
  @Column({ name: "install_id" })
  installId!: string;

  @Column({ name: "push_token" })
  pushToken!: string;

  @Column({ name: "platform" })
  platform!: "ios" | "android";

  @ManyToOne(() => User, { onDelete: "CASCADE", eager: false })
  user!: User;

  @Column({ name: "user_id" })
  userId!: string;

  @Column({ name: "disabled_at", type: "timestamptz", nullable: true })
  disabledAt!: Date | null;

  @CreateDateColumn({ name: "created_at" })
  createdAt!: Date;
}

import { DataSource, IsNull } from "typeorm";
import { Device } from "./entities";

export interface PushGateway {
  send(token: string, platform: string, payload: { title: string; body: string }): Promise<"ok" | "unregistered">;
}

export interface DirectPushRequest {
  installId?: string;
  title: string;
  body: string;
}

export class PushService {
  constructor(private readonly ds: DataSource, private readonly gateway: PushGateway) {}

  async notifyUser(userId: string, title: string, body: string): Promise<number> {
    const devices = await this.ds.getRepository(Device).find({
      where: { userId, disabledAt: IsNull() },
      order: { createdAt: "DESC" },
      take: 10,
    });
    let delivered = 0;
    for (const d of devices) {
      if (await this.deliver(d, title, body)) delivered++;
    }
    return delivered;
  }

  async notifyInstall(req: DirectPushRequest): Promise<boolean> {
    const device = await this.ds.getRepository(Device).findOneBy({
      installId: req.installId,
      disabledAt: IsNull(),
    });
    if (!device) return false;
    return this.deliver(device, req.title, req.body);
  }

  private async deliver(device: Device, title: string, body: string): Promise<boolean> {
    const result = await this.gateway.send(device.pushToken, device.platform, { title, body });
    if (result === "unregistered") {
      await this.ds.getRepository(Device).update({ id: device.id }, { disabledAt: new Date() });
      return false;
    }
    return true;
  }
}

import { PushService, DirectPushRequest } from "./pushService";

export interface Req { body: unknown; auth: { service: string } | null; }
export interface Res { status: number; json: unknown; }

export async function handleDirectPush(svc: PushService, req: Req): Promise<Res> {
  if (!req.auth) return { status: 401, json: { error: "unauthenticated" } };
  const b = (req.body ?? {}) as Partial<DirectPushRequest>;
  if (typeof b.title !== "string" || typeof b.body !== "string") {
    return { status: 400, json: { error: "title and body are required" } };
  }
  if (b.title.length > 120 || b.body.length > 1000) {
    return { status: 400, json: { error: "payload too long" } };
  }
  const sent = await svc.notifyInstall({ installId: b.installId, title: b.title, body: b.body });
  return sent ? { status: 202, json: { status: "queued" } } : { status: 404, json: { error: "device_not_found" } };
}

export async function handleUserPush(svc: PushService, userId: string, req: Req): Promise<Res> {
  if (!req.auth) return { status: 401, json: { error: "unauthenticated" } };
  const b = (req.body ?? {}) as { title?: unknown; body?: unknown };
  if (typeof b.title !== "string" || typeof b.body !== "string") {
    return { status: 400, json: { error: "title and body are required" } };
  }
  const delivered = await svc.notifyUser(userId, b.title, b.body);
  return { status: 202, json: { delivered } };
}
